mapper.insert:
/*com.moyeo.mapper.RoomMapper.insertRoom*/
INSERT INTO ROOM_MAST (
            ROOM_NM
          , ROOM_TYPE_CD
          , ROOM_QST_NUM
          , PEOPLE_NUM
          , ROOM_USE_YN
) VALUES (  #{roomNm}
          , #{roomTypeCd}
          , #{roomQnum}
          , 1
          , 'Y'
)

/*com.moyeo.mapper.RoomMapper.insertRoomPassword*/
INSERT INTO ROOM_PW_MAST (
            ROOM_ID
          , FIRST_WORD
          , SECOND_WORD
          , THIRD_WORD
) VALUES (  #{roomId}
          , #{firstWord}
          , #{secondWord}
          , #{thirdWord}
)

/*com.moyeo.mapper.RoomMapper.insertUserInfo*/
INSERT INTO USER_MAST (
            USER_NM
          , USER_IMG
          , USER_COLOR
) VALUES (  #{userName}
          , #{userImg}
          , #{userColor}
)

/*com.moyeo.mapper.RoomMapper.insertRoomUserMap*/
INSERT INTO ROOM_USER_MAP (
            ROOM_ID
          , USER_ID
          , USER_SNO
) VALUES (  #{roomId}
          , #{userId}
          , (SELECT COUNT(*) + 1
               FROM ROOM_MAST
              WHERE ROOM_ID = #{roomId}
            )
)
